set -euo pipefail
REPO=github/copilot-sdk
PR_NUMBER=2175
COMMIT=d779d146
THREADS=$(gh api graphql -F number="$PR_NUMBER" -f query='query($number: Int!) { repository(owner: "github", name: "copilot-sdk") { pullRequest(number: $number) { reviewThreads(first: 100) { nodes { id isResolved comments(first: 1) { nodes { databaseId } } } } } } }')
for COMMENT_ID in 3686624237 3686624263 3686624276 3686624289 3686624308 3686624335; do
  THREAD=$(printf '%s' "$THREADS" | jq --argjson id "$COMMENT_ID" -c '.data.repository.pullRequest.reviewThreads.nodes[] | select(.comments.nodes[0].databaseId == $id)')
  [ -n "$THREAD" ] || { echo "Missing thread for comment $COMMENT_ID"; exit 1; }
  if [ "$(printf '%s' "$THREAD" | jq -r '.isResolved')" = true ]; then echo "Comment $COMMENT_ID already resolved; skipping"; continue; fi
  case "$COMMENT_ID" in
    3686624237) EXPLANATION='Restored the third fallback by locating the bundled copilot executable on PATH and checking its runtime.node sibling only when the classifier resource is absent.' ;;
    3686624263) EXPLANATION='Normalized the configured CLI path to an absolute path before resolving runtime.node, so JNA always receives an absolute path.' ;;
    3686624276) EXPLANATION='Moved COPILOT_CLI_PATH resolution ahead of platform detection and version-resource loading.' ;;
    3686624289) EXPLANATION='The finally block now always deletes the caller temp path; deletion is harmless after a successful move and removes losing-race files.' ;;
    3686624308) EXPLANATION='Added distinct resources for two classifiers and now verifies the extracted bytes come from the requested classifier.' ;;
    3686624335) EXPLANATION='Atomic publication now uses REPLACE_EXISTING, repairing invalid cache entries safely while retaining atomic replacement and concurrent-writer correctness.' ;;
  esac
  gh api --method POST "/repos/$REPO/pulls/$PR_NUMBER/comments/$COMMENT_ID/replies" -f "body=Fixed in $COMMIT. $EXPLANATION" >/dev/null
  THREAD_ID=$(printf '%s' "$THREAD" | jq -r '.id')
  gh api graphql -f query="mutation { resolveReviewThread(input: {threadId: \"$THREAD_ID\"}) { thread { id isResolved } } }" --jq '.data.resolveReviewThread.thread | select(.isResolved == true) | .id'
done

